def permitted(name,user):
    if name in REPLENISHMENT and user['role'] not in ['SupplyChainManager','WarehouseManager','WarehouseSupervisor','Storekeeper','PurchaseManager','PurchaseOfficer']:raise HTTPException(403,'Replenishment report access is required')
    if name in EXEC and user['role']!='SupplyChainManager':raise HTTPException(403,f"Role '{user['role']}' is not permitted to perform this action")
    if name in PROC and user['role'] not in ['SupplyChainManager','PurchaseManager','PurchaseOfficer']:raise HTTPException(403,f"Role '{user['role']}' is not permitted to perform this action")
    if name in FINANCE and user['role']!='SupplyChainManager':raise HTTPException(403,f"Role '{user['role']}' is not permitted to perform this action")
    if name in WAREHOUSE_REPORTS and user['role'] not in ['SupplyChainManager','WarehouseManager','WarehouseSupervisor','Storekeeper']:raise HTTPException(403,f"Role '{user['role']}' is not permitted to perform this action")
def make_handler(name,sql):
    def handler(user:User):permitted(name,user);return scoped_report(sql,user)
    handler.__name__='report_'+name.replace('-','_');return handler
for _name,_sql in QUERIES.items():router.add_api_route('/'+_name,make_handler(_name,_sql),methods=['GET'])

