def make_scoped(name,sql):
    def handler(user:User):
        permitted(name,user)
        ids=user['warehouse_ids'];
        if not ids:return []
        marks=','.join('?' for _ in ids);occurrences=sql.count('{marks}')
        return scoped_report(sql.format(marks=marks),user,ids*occurrences)
    handler.__name__='scoped_'+name.replace('-','_');return handler
for _name,_sql in SCOPED.items():
    if _name not in QUERIES:router.add_api_route('/'+_name,make_scoped(_name,_sql),methods=['GET'])

